import sys
from itertools import combinations

def combine(n, k):
    return list(combinations(range(1, n + 1), k))

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n, k = int(data[0]), int(data[1])
    for c in combine(n, k):
        print(' '.join(map(str, c)))

